# ==============================================================================
# TRANSLATION APPLICATION ENGINE
# ==============================================================================


def translate_descriptions(obj, lang_map):
    """Recursively translate all 'description' string values in a JSON-like structure."""
    if isinstance(obj, dict):
        result = {}
        for k, v in obj.items():
            if k == "description" and isinstance(v, str):
                translated = lang_map.get(v)
                if translated is not None:
                    result[k] = translated
                else:
                    # Keep original if not found in map
                    result[k] = v
            else:
                result[k] = translate_descriptions(v, lang_map)
        return result
    elif isinstance(obj, list):
        return [translate_descriptions(item, lang_map) for item in obj]
    else:
        return obj


def process_all():
    """Process all English schemas and generate translations."""
    lang_maps = {"es": ES, "de": DE, "pt": PT}
    total = 0
    missing_es = set()
    missing_de = set()
    missing_pt = set()

    for schema_file in sorted(BASE.glob("*/schema.en.json")):
        folder = schema_file.parent
        with open(schema_file, "r", encoding="utf-8") as f:
            data = json.load(f)

        # Collect missing descriptions
        def collect_desc(obj):
            if isinstance(obj, dict):
                if "description" in obj and isinstance(obj["description"], str):
                    d = obj["description"]
                    if d not in ES:
                        missing_es.add(d)
                    if d not in DE:
                        missing_de.add(d)
                    if d not in PT:
                        missing_pt.add(d)
                for v in obj.values():
                    collect_desc(v)
            elif isinstance(obj, list):
                for item in obj:
                    collect_desc(item)

        collect_desc(data)

        for lang, lang_map in lang_maps.items():
            translated = translate_descriptions(deepcopy(data), lang_map)
            out_path = folder / f"schema.{lang}.json"
            with open(out_path, "w", encoding="utf-8") as f:
                json.dump(translated, f, indent=2, ensure_ascii=False)
                f.write("\n")
            total += 1

    print(f"Generated {total} translated files ({total // 3} schemas × 3 languages)")
    if missing_es:
        print(f"\n{len(missing_es)} descriptions missing Spanish translations:")
        for d in sorted(missing_es):
            print(f"  [{len(d)} chars] {d[:120]}...")
    if missing_de:
        print(f"\n{len(missing_de)} descriptions missing German translations:")
        for d in sorted(missing_de):
            print(f"  [{len(d)} chars] {d[:120]}...")
    if missing_pt:
        print(f"\n{len(missing_pt)} descriptions missing Portuguese translations:")
        for d in sorted(missing_pt):
            print(f"  [{len(d)} chars] {d[:120]}...")


if __name__ == "__main__":
    process_all()
